const ENTRY = '/home/user/thyrox/.thyrox/pool-worktrees/d4ab92b4efb0/4/src/packages/cli/src/print.ts'
const result = await Bun.build({
  entrypoints: [ENTRY],
  target: 'bun',
  metafile: true,
  throw: false,
  plugins: [{
    name: 'external-third-party',
    setup(build) {
      build.onResolve({ filter: /\.node$/ }, args => ({ path: args.path, external: true }))
      build.onResolve({ filter: /^[^./]/ }, args => {
        if (args.path.startsWith('node:') || args.path.startsWith('bun:')) return undefined
        if (args.path.startsWith('@thyrox/')) return undefined
        return { path: args.path, external: true }
      })
    },
  }],
})
console.log('success', result.success)
if (!result.success) { for (const log of result.logs) console.log(String(log)) }
else {
  const inputs = Object.keys(result.metafile!.inputs)
  console.log('total', inputs.length)
  console.log(inputs.filter(p => p.includes('/cli/src/index.ts')))
}
EOF
